runs-on: windows-latest
    steps:
      - uses: actions/checkout@v5

      - uses: actions/setup-dotnet@v4
        with:
          dotnet-version: ${{ env.DOTNET_VERSION }}

      - name: Generate production appsettings from secrets
        working-directory: ./LigaCup.API
        shell: pwsh
        env:
          JWT_KEY: ${{ secrets.JWT_KEY }}
          ADMIN_USERNAME: ${{ secrets.ADMIN_USERNAME }}
          ADMIN_PASSWORD: ${{ secrets.ADMIN_PASSWORD }}
          ADMIN_EMAIL: ${{ secrets.ADMIN_EMAIL }}
          WEB_ORIGIN: ${{ vars.WEB_ORIGIN }}
          API_ORIGIN: ${{ vars.API_ORIGIN }}
        run: |
          if ([string]::IsNullOrWhiteSpace($env:JWT_KEY) -or $env:JWT_KEY.Length -lt 32) {
            throw "The JWT_KEY secret must be set and at least 32 characters long."
          }

          $origin = if ([string]::IsNullOrWhiteSpace($env:WEB_ORIGIN)) { '${{ env.DEFAULT_WEB_ORIGIN }}' } else { $env:WEB_ORIGIN }
          $apiOrigin = if ([string]::IsNullOrWhiteSpace($env:API_ORIGIN)) { '${{ env.DEFAULT_API_ORIGIN }}' } else { $env:API_ORIGIN }
          $origin = $origin.Trim().TrimEnd('/').TrimEnd('.')
          $apiOrigin = $apiOrigin.Trim().TrimEnd('/').TrimEnd('.')

          # Rejects requests arriving with an unexpected Host header.
          $apiHost = ([Uri]$apiOrigin).Host

          $config = @{
            Database          = @{ Provider = 'Sqlite' }
            ConnectionStrings = @{ LigaCupSqlite = 'Data Source=App_Data/ligacup.db' }
            Jwt               = @{
              Issuer        = 'LigaCup'
              Audience      = 'LigaCup.Clients'
              Key           = $env:JWT_KEY
              ExpiryMinutes = 60
              RefreshExpiryDays = 30
            }
            Admin             = @{
              Username = $env:ADMIN_USERNAME
              Password = $env:ADMIN_PASSWORD
              Email    = $env:ADMIN_EMAIL
            }
            Cors              = @{ AllowedOrigins = @($origin) }
            Logging           = @{ LogLevel = @{ Default = 'Warning'; 'LigaCup' = 'Information' } }
            AllowedHosts      = '*'
          }

          $config | ConvertTo-Json -Depth 6 | Set-Content -Path 'appsettings.Production.json' -Encoding UTF8

      - name: Publish API
        run: >
          dotnet publish ${{ env.PROJECT_PATH }}
          --configuration Release
          --runtime ${{ env.RUNTIME_IDENTIFIER }}
          --self-contained true
          -p:CopyLocalLockFileAssemblies=true
          --output ${{ env.PUBLISH_PATH }}

      - name: Verify API artifact
        shell: pwsh
        run: |
          $publishDir = '${{ env.PUBLISH_PATH }}'
          foreach ($required in @('LigaCup.API.exe', 'web.config', 'appsettings.Production.json')) {
            if (-not (Test-Path (Join-Path $publishDir $required))) {
              throw "Missing $required in publish output."
            }
          }

          $webConfig = Get-Content (Join-Path $publishDir 'web.config') -Raw
          if ($webConfig -notmatch 'processPath="\.\\LigaCup\.API\.exe"') {
            throw 'web.config processPath is not set to .\LigaCup.API.exe.'
          }
          if ($webConfig -notmatch 'hostingModel="OutOfProcess"') {
            throw 'web.config hostingModel is not OutOfProcess.'
          }

{
  "ConnectionStrings": {
    "LigaCupSqlite": "Data Source=App_Data/ligacup.dev.db"
  },
  "Admin": {
    "Username": "Sez",
    "Email": "moyumbnm@hotmail.com"
  },
  "Jwt": {
    "Key": "local-development-only-key-not-used-in-production-0123456789"
  },
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "Microsoft.EntityFrameworkCore.Database.Command": "Warning",
      "Microsoft.AspNetCore.SignalR": "Information"
    }
  }
}

