export class App {
  protected readonly auth = inject(AuthService);
  protected readonly i18n = inject(I18nService);
  protected readonly t = this.i18n.t;
}

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from './auth.service';

export const adminGuard: CanActivateFn = (_route, state) => {
    const auth = inject(AuthService);
    const router = inject(Router);

    return auth.isLoggedIn()
        ? true
        : router.createUrlTree(['/login'], { queryParams: { returnUrl: state.url } });
};

/** Account management is limited to administrators. */
export const administratorGuard: CanActivateFn = (_route, state) => {
    const auth = inject(AuthService);
    const router = inject(Router);

    if (!auth.isLoggedIn()) {
        return router.createUrlTree(['/login'], { queryParams: { returnUrl: state.url } });
    }

    return auth.isAdmin() ? true : router.createUrlTree(['/admin']);
};

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { environment } from '../../environments/environment';
import {
    CreateUserRequest,
    Group,
    Match,
    MatchEventType,
    MatchStage,
    MatchStatus,
    Player,
    SaveTournamentRequest,
    Team,
    TournamentDetail,
    TournamentSummary,
    UpdateUserRequest,
    User,
} from './models';

@Injectable({ providedIn: 'root' })

export class ApiService {
    private readonly http = inject(HttpClient);
    private readonly base = environment.apiBaseUrl;

    getTournaments() {
        return this.http.get<TournamentSummary[]>(`${this.base}/api/tournaments`);
    }

    getUsers() {
        return this.http.get<User[]>(`${this.base}/api/admin/users`);
    }

    createUser(request: CreateUserRequest) {
        return this.http.post<User>(`${this.base}/api/admin/users`, request);
    }

    updateUser(id: number, request: UpdateUserRequest) {
        return this.http.put<User>(`${this.base}/api/admin/users/${id}`, request);
    }

    resetUserPassword(id: number, password: string) {
        return this.http.put<void>(`${this.base}/api/admin/users/${id}/password`, { password });
    }

    deleteUser(id: number) {
        return this.http.delete<void>(`${this.base}/api/admin/users/${id}`);
    }

    getTournament(slug: string) {
        return this.http.get<TournamentDetail>(`${this.base}/api/tournaments/${slug}`);
    }

    createTournament(request: SaveTournamentRequest) {
        return this.http.post<string>(`${this.base}/api/admin/tournaments`, request);
    }

    updateTournament(id: number, request: SaveTournamentRequest) {
        return this.http.put<string>(`${this.base}/api/admin/tournaments/${id}`, request);
    }

    deleteTournament(id: number) {
        return this.http.delete<void>(`${this.base}/api/admin/tournaments/${id}`);
    }

    createGroup(tournamentId: number, name: string, sortOrder: number) {
        return this.http.post<Group>(`${this.base}/api/admin/tournaments/${tournamentId}/groups`, {
            name,
            sortOrder,
        });
    }

    deleteGroup(tournamentId: number, groupId: number) {
        return this.http.delete<void>(
            `${this.base}/api/admin/tournaments/${tournamentId}/groups/${groupId}`,
        );
    }

    saveTeam(tournamentId: number, teamId: number | null, body: Partial<Team>) {
        const payload = {
            name: body.name,
            shortName: body.shortName ?? null,
            colorHex: body.colorHex ?? null,
            logoUrl: body.logoUrl ?? null,
            manager: body.manager ?? null,
            groupId: body.groupId ?? null,
            pointsAdjustment: body.pointsAdjustment ?? 0,
        };

        return teamId
            ? this.http.put<Team>(
                `${this.base}/api/admin/tournaments/${tournamentId}/teams/${teamId}`,
                payload,
            )
            : this.http.post<Team>(`${this.base}/api/admin/tournaments/${tournamentId}/teams`, payload);
    }

    deleteTeam(tournamentId: number, teamId: number) {
        return this.http.delete<void>(
            `${this.base}/api/admin/tournaments/${tournamentId}/teams/${teamId}`,
        );

}

    savePlayer(playerId: number | null, body: Partial<Player>) {
        const payload = {
            teamId: body.teamId,
            name: body.name,
            shirtNumber: body.shirtNumber ?? null,
            position: body.position ?? null,
            isActive: body.isActive ?? true,
        };

        return playerId
            ? this.http.put<Player>(`${this.base}/api/admin/tournaments/players/${playerId}`, payload)
            : this.http.post<Player>(`${this.base}/api/admin/tournaments/players`, payload);
    }

    deletePlayer(playerId: number) {
        return this.http.delete<void>(`${this.base}/api/admin/tournaments/players/${playerId}`);
    }

    generateFixtures(
        tournamentId: number,
        includeGroupStage: boolean,
        includeKnockoutStage: boolean,
        replaceExisting: boolean,
    ) {
        return this.http.post<{ generated: number }>(
            `${this.base}/api/admin/tournaments/${tournamentId}/fixtures`,
            { includeGroupStage, includeKnockoutStage, replaceExisting },
        );
    }

    seedKnockout(tournamentId: number) {
        return this.http.post<{ seeded: number }>(
            `${this.base}/api/admin/tournaments/${tournamentId}/knockout/seed`,
            {},
        );
    }

    saveMatch(
        tournamentId: number,
        matchId: number | null,
        body: {
            groupId: number | null;
            stage: MatchStage;
            round: number;
            homeTeamId: number | null;
            awayTeamId: number | null;
            homePlaceholder: string | null;
            awayPlaceholder: string | null;
            kickoffUtc: string | null;
            venue: string | null;
        },
    ) {
        return matchId
            ? this.http.put<Match>(
                `${this.base}/api/admin/tournaments/${tournamentId}/matches/${matchId}`,
                body,
            )
            : this.http.post<Match>(`${this.base}/api/admin/tournaments/${tournamentId}/matches`, body);
    }

    deleteMatch(tournamentId: number, matchId: number) {
        return this.http.delete<void>(
            `${this.base}/api/admin/tournaments/${tournamentId}/matches/${matchId}`,
        );
    }

    adjustScore(matchId: number, side: 'home' | 'away', delta: 1 | -1) {
        return this.http.post<Match>(
            `${this.base}/api/live/matches/${matchId}/score/${side}/${delta}`,
            {},
        );
    }

    setScore(
        matchId: number,
        homeScore: number,
        awayScore: number,
        homePenalties: number | null,

awayPenalties: number | null,
    ) {
        return this.http.put<Match>(`${this.base}/api/live/matches/${matchId}/score`, {
            homeScore,
            awayScore,
            homePenalties,
            awayPenalties,
        });
    }

    setStatus(matchId: number, status: MatchStatus) {
        return this.http.put<Match>(`${this.base}/api/live/matches/${matchId}/status`, { status });
    }

    setStoppage(matchId: number, stoppageMinutes: number) {
        return this.http.put<Match>(`${this.base}/api/live/matches/${matchId}/stoppage`, {
            stoppageMinutes,
        });
    }

    addEvent(
        matchId: number,
        teamId: number,
        playerId: number | null,
        type: MatchEventType,
        minute: number,
        note: string | null,
    ) {
        return this.http.post<Match>(`${this.base}/api/live/matches/${matchId}/events`, {
            teamId,
            playerId,
            type,
            minute,
            note,
        });
    }

    deleteEvent(matchId: number, eventId: number) {
        return this.http.delete<Match>(`${this.base}/api/live/matches/${matchId}/events/${eventId}`);
    }
}

import {
    HttpErrorResponse,
    HttpEvent,
    HttpHandlerFn,
    HttpInterceptorFn,
    HttpRequest,
    HttpClient,
} from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Router } from '@angular/router';
import { Observable, catchError, from, switchMap, tap, throwError } from 'rxjs';
import { environment } from '../../environments/environment';
import { AuthResponse } from './models';

const STORAGE_KEY = 'ligacup.auth';

/** Renew this far before the access token expires, so a slow request never races the clock. */
const RENEW_BEFORE_MS = 60_000;

@Injectable({ providedIn: 'root' })

export class AuthService {
    private readonly http = inject(HttpClient);
    private readonly router = inject(Router);
    private readonly session = signal<AuthResponse | null>(restore());

    /** Shared so several parallel requests trigger only one refresh call. */
    private inFlightRefresh: Promise<AuthResponse | null> | null = null;

    readonly user = computed(() => this.session());
    readonly isLoggedIn = computed(() => this.session() !== null);
    readonly isAdmin = computed(() => this.session()?.role === 'Admin');

    login(username: string, password: string) {
        return this.http
            .post<AuthResponse>(`${environment.apiBaseUrl}/api/auth/login`, { username, password })
            .pipe(tap((response) => this.store(response)));
    }

    async logout(): Promise<void> {
        const refreshToken = this.session()?.refreshToken;
        this.clear();

        if (refreshToken) {
            try {
                await this.http
                    .post<void>(`${environment.apiBaseUrl}/api/auth/logout`, { refreshToken })
                    .toPromise();
            } catch {
                // The local session is already gone, so a failed revoke is not worth surfacing.
            }
        }

        void this.router.navigate(['/']);
    }

    /** The access token, refreshed first when it is expired or about to be. */
    async validToken(): Promise<string | null> {
        const session = this.session();
        if (!session) {
            return null;
        }

        const expiresAt = new Date(session.expiresUtc).getTime();
        if (expiresAt - Date.now() > RENEW_BEFORE_MS) {
            return session.token;
        }

        const refreshed = await this.refresh();
        return refreshed?.token ?? null;
    }

    async refresh(): Promise<AuthResponse | null> {
        this.inFlightRefresh ??= this.performRefresh().finally(() => {
            this.inFlightRefresh = null;
        });

        return this.inFlightRefresh;
    }

    private async performRefresh(): Promise<AuthResponse | null> {
        const refreshToken = this.session()?.refreshToken;
        if (!refreshToken) {
            this.clear();
            return null;
        }

        try {
            const response = await this.http
                .post<AuthResponse>(`${environment.apiBaseUrl}/api/auth/refresh`, { refreshToken })
                .toPromise();

            if (!response) {
                this.clear();
                return null;
            }

            this.store(response);
            return response;
        } catch {
            this.clear();

return null;
        }
    }

    private store(response: AuthResponse): void {
        this.session.set(response);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(response));
    }

    private clear(): void {
        this.session.set(null);
        localStorage.removeItem(STORAGE_KEY);
    }
}

/**
 * Keeps a stored session usable across restarts. The access token may well be expired
 * here, which is fine: the refresh token is what proves the session is still valid.
 */

function restore(): AuthResponse | null {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
        return null;
    }

    try {
        const parsed = JSON.parse(raw) as AuthResponse;
        return parsed.refreshToken ? parsed : null;
    } catch {
        localStorage.removeItem(STORAGE_KEY);
        return null;
    }
}

const AUTH_FREE_PATHS = ['/api/auth/login', '/api/auth/refresh', '/api/auth/logout'];

export const authInterceptor: HttpInterceptorFn = (request, next) => {
    const auth = inject(AuthService);

    // Only attach the bearer token to our own API so it never leaks to third-party hosts.
    const isOwnApi = request.url.startsWith(environment.apiBaseUrl);
    const isAuthCall = AUTH_FREE_PATHS.some((path) => request.url.includes(path));

    if (!isOwnApi || isAuthCall) {
        return next(request);
    }

    return from(auth.validToken()).pipe(
        switchMap((token) => {
            const authorised = token
                ? request.clone({ setHeaders: { Authorization: `Bearer ${token}` } })
                : request;

            return next(authorised).pipe(
                catchError((error: unknown) => retryOnce(error, auth, authorised, next)),
            );
        }),
    );
};

/** A 401 can still mean a token revoked server-side, so try one forced refresh. */
function retryOnce(
    error: unknown,
    auth: AuthService,
    request: HttpRequest<unknown>,
    next: HttpHandlerFn,
): Observable<HttpEvent<unknown>> {
    if (!(error instanceof HttpErrorResponse) || error.status !== 401) {
        return throwError(() => error);
    }

    return from(auth.refresh()).pipe(
        switchMap((session) => {
            if (!session) {
                return throwError(() => error);
            }

            return next(request.clone({ setHeaders: { Authorization: `Bearer ${session.token}` } }));
        }),
    );
}

