export class SelectField<T = unknown> implements ControlValueAccessor {
    readonly options = input<SelectOption<T>[]>([]);
    readonly placeholder = input('');
    readonly label = input('');

    private readonly host = inject(ElementRef<HTMLElement>);
    private readonly instance = nextId++;

    protected readonly listId = `select-list-${this.instance}`;
    protected readonly open = signal(false);
    protected readonly activeIndex = signal(0);
    protected readonly value = signal<T | null>(null);
    protected readonly isDisabled = signal(false);

    protected readonly selectedOption = computed(
        () => this.options().find((option) => option.value === this.value()) ?? null,
    );

    private onChange: (value: T | null) => void = () => { };
    private onTouched: () => void = () => { };

    writeValue(value: T | null): void {
        this.value.set(value);
    }

    registerOnChange(fn: (value: T | null) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        this.isDisabled.set(isDisabled);
    }

    protected optionId(index: number): string {
        return `${this.listId}-option-${index}`;
    }

    protected toggle(): void {
        this.open() ? this.close() : this.openList();
    }

    protected choose(index: number): void {
        const option = this.options()[index];
        if (!option || option.disabled) {
            return;
        }

        this.value.set(option.value);
        this.onChange(option.value);
        this.close();
    }

    protected onKeydown(event: KeyboardEvent): void {
        if (!this.open()) {
            if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(event.key)) {
                event.preventDefault();
                this.openList();
            }
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.move(1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.move(-1);
                break;
            case 'Home':
                event.preventDefault();
                this.activeIndex.set(0);
                break;
            case 'End':
                event.preventDefault();

this.activeIndex.set(this.options().length - 1);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.choose(this.activeIndex());
                break;
            case 'Escape':
            case 'Tab':
                this.close();
                break;
        }
    }

    @HostListener('document:click', ['$event'])
    protected onDocumentClick(event: MouseEvent): void {
        if (this.open() && !this.host.nativeElement.contains(event.target as Node)) {
            this.close();
        }
    }

    private openList(): void {
        if (this.isDisabled()) {
            return;
        }

        const selected = this.options().findIndex((option) => option.value === this.value());
        this.activeIndex.set(selected >= 0 ? selected : 0);
        this.open.set(true);
    }

    private close(): void {
        if (!this.open()) {
            return;
        }

        this.open.set(false);
        this.onTouched();
    }

    /** Steps over disabled options so keyboard users never land on one. */
    private move(direction: number): void {
        const options = this.options();
        if (options.length === 0) {
            return;
        }

        let index = this.activeIndex();
        for (let step = 0; step < options.length; step++) {
            index = (index + direction + options.length) % options.length;
            if (!options[index].disabled) {
                this.activeIndex.set(index);
                return;
            }
        }
    }
}

