using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using LigaCup.ApplicationService.Contracts;
using LigaCup.Domain.Entities;
using LigaCup.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;

namespace LigaCup.ApplicationService.Security;

public class JwtOptions
{
    public const string SectionName = "Jwt";

    public string Issuer { get; set; } = "LigaCup";
    public string Audience { get; set; } = "LigaCup.Clients";
    public string Key { get; set; } = string.Empty;

    /// <summary>Short lived on purpose. The refresh token is what keeps someone signed in.</summary>
    public int ExpiryMinutes { get; set; } = 60;

    public int RefreshExpiryDays { get; set; } = 30;
}

public class AuthService(LigaCupContext dbContext, IOptions<JwtOptions> jwtOptions, ILogger<AuthService> logger)
{
    private readonly JwtOptions options = jwtOptions.Value;

    public async Task<AuthResponse?> LoginAsync(LoginRequest request, CancellationToken cancellationToken = default)
    {
        // Accepts the username or the email address, since people rarely remember which they registered with.
        var identifier = (request.Username ?? string.Empty).Trim().ToLower();

        var user = await dbContext.Users.FirstOrDefaultAsync(
            candidate => candidate.IsActive
                && (candidate.Username.ToLower() == identifier
                    || (candidate.Email != null && candidate.Email.ToLower() == identifier)),
            cancellationToken);

        if (user is null || !PasswordHasher.Verify(request.Password, user.PasswordHash))
        {
            logger.LogWarning("Failed login attempt for {Identifier}", identifier);
            return null;
        }

        user.LastLoginUtc = DateTime.UtcNow;

        var response = CreateToken(user, await IssueRefreshTokenAsync(user, cancellationToken));
        await dbContext.SaveChangesAsync(cancellationToken);

        return response;
    }

    /// <summary>
    /// Swaps a refresh token for a new pair. The old token is revoked on use, so a stolen
    /// token stops working as soon as the real client refreshes.
    /// </summary>

public async Task<AuthResponse?> RefreshAsync(string refreshToken, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(refreshToken))
        {
            return null;
        }

        var hash = RefreshTokenGenerator.Hash(refreshToken);
        var now = DateTime.UtcNow;

        var stored = await dbContext.RefreshTokens
            .Include(token => token.User)
            .FirstOrDefaultAsync(token => token.TokenHash == hash, cancellationToken);

        if (stored?.User is null || !stored.IsActive(now) || !stored.User.IsActive)
        {
            logger.LogWarning("Rejected a refresh token that was expired, revoked or unknown.");
            return null;
        }

        stored.RevokedUtc = now;

        var response = CreateToken(stored.User, await IssueRefreshTokenAsync(stored.User, cancellationToken));
        await dbContext.SaveChangesAsync(cancellationToken);

        return response;
    }

    public async Task RevokeAsync(string refreshToken, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(refreshToken))
        {
            return;
        }

        var hash = RefreshTokenGenerator.Hash(refreshToken);
        var stored = await dbContext.RefreshTokens.FirstOrDefaultAsync(token => token.TokenHash == hash, cancellationToken);

        if (stored is not null && stored.RevokedUtc is null)
        {
            stored.RevokedUtc = DateTime.UtcNow;
            await dbContext.SaveChangesAsync(cancellationToken);
        }
    }

    private async Task<string> IssueRefreshTokenAsync(User user, CancellationToken cancellationToken)
    {
        var token = RefreshTokenGenerator.Create();

        dbContext.RefreshTokens.Add(new RefreshToken
        {
            UserId = user.Id,
            TokenHash = RefreshTokenGenerator.Hash(token),
            ExpiresUtc = DateTime.UtcNow.AddDays(Math.Max(1, options.RefreshExpiryDays))
        });

        await RemoveStaleTokensAsync(user.Id, cancellationToken);
        return token;
    }

    private async Task RemoveStaleTokensAsync(int userId, CancellationToken cancellationToken)
    {
        var now = DateTime.UtcNow;
        var revokedCutoff = now.AddDays(-1);

        var stale = await dbContext.RefreshTokens
            .Where(token => token.UserId == userId
                && (token.ExpiresUtc < now || (token.RevokedUtc != null && token.RevokedUtc < revokedCutoff)))
            .ToListAsync(cancellationToken);

        dbContext.RefreshTokens.RemoveRange(stale);
    }

private AuthResponse CreateToken(User user, string refreshToken)
    {
        var expiresUtc = DateTime.UtcNow.AddMinutes(options.ExpiryMinutes);
        var signingKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(options.Key));

        var claims = new List<Claim>
        {
            new(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
            new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new(ClaimTypes.Name, user.Username),
            new(ClaimTypes.Role, user.Role.ToString())
        };

        var token = new JwtSecurityToken(
            issuer: options.Issuer,
            audience: options.Audience,
            claims: claims,
            expires: expiresUtc,
            signingCredentials: new SigningCredentials(signingKey, SecurityAlgorithms.HmacSha256));

        return new AuthResponse(
            new JwtSecurityTokenHandler().WriteToken(token),
            expiresUtc,
            user.Username,
            user.Role.ToString(),
            refreshToken);
    }
}

using System.Security.Cryptography;
using System.Text;

namespace LigaCup.ApplicationService.Security;

/// <summary>PBKDF2-SHA256 hashing. The salt and iteration count travel with the hash.</summary>
public static class PasswordHasher
{
    private const int SaltSize = 16;
    private const int KeySize = 32;
    private const int Iterations = 210_000;
    private const string Prefix = "pbkdf2.sha256";

    public static string Hash(string password)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(password);

        var salt = RandomNumberGenerator.GetBytes(SaltSize);
        var key = Rfc2898DeriveBytes.Pbkdf2(
            Encoding.UTF8.GetBytes(password), salt, Iterations, HashAlgorithmName.SHA256, KeySize);

        return $"{Prefix}.{Iterations}.{Convert.ToBase64String(salt)}.{Convert.ToBase64String(key)}";
    }

    public static bool Verify(string password, string storedHash)
    {
        if (string.IsNullOrWhiteSpace(password) || string.IsNullOrWhiteSpace(storedHash))
        {
            return false;
        }

        var parts = storedHash.Split('.');
        if (parts.Length != 5 || parts[0] != "pbkdf2" || parts[1] != "sha256" || !int.TryParse(parts[2], out var iterations))
        {
            return false;
        }

        try
        {
            var salt = Convert.FromBase64String(parts[3]);
            var expected = Convert.FromBase64String(parts[4]);
            var actual = Rfc2898DeriveBytes.Pbkdf2(
                Encoding.UTF8.GetBytes(password), salt, iterations, HashAlgorithmName.SHA256, expected.Length);

            return CryptographicOperations.FixedTimeEquals(expected, actual);
        }
        catch (FormatException)
        {
            return false;
        }
    }
}

using System.Security.Cryptography;
using System.Text;

namespace LigaCup.ApplicationService.Security;

/// <summary>
/// Refresh tokens are random opaque strings. Only a SHA-256 hash is persisted, so the
/// stored value cannot be replayed, and a plain hash is enough because the token itself
/// already has full entropy and needs no salting.
/// </summary>
public static class RefreshTokenGenerator
{
    public static string Create() => Convert.ToBase64String(RandomNumberGenerator.GetBytes(48));

    public static string Hash(string token) =>
        Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
}

using LigaCup.ApplicationService.Contracts;
using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;
using LigaCup.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace LigaCup.ApplicationService.Security;

/// <summary>
/// Administrator-only account management. Every mutation is guarded against
/// leaving the site with no way back in, which is easy to do by accident.
/// </summary>
public class UserService(LigaCupContext dbContext)
{
    public const int MinimumPasswordLength = 8;

    public async Task<IReadOnlyList<UserDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var users = await dbContext.Users
            .AsNoTracking()
            .OrderBy(user => user.Username)
            .ToListAsync(cancellationToken);

        return users.Select(ToDto).ToList();
    }

    public async Task<UserDto> CreateAsync(CreateUserRequest request, CancellationToken cancellationToken = default)
    {
        var username = (request.Username ?? string.Empty).Trim();

        if (string.IsNullOrWhiteSpace(username))
        {
            throw new InvalidOperationException("A username is required.");
        }

        if ((request.Password ?? string.Empty).Length < MinimumPasswordLength)
        {
            throw new InvalidOperationException($"The password must be at least {MinimumPasswordLength} characters.");
        }

        var normalized = username.ToLower();
        if (await dbContext.Users.AnyAsync(user => user.Username.ToLower() == normalized, cancellationToken))
        {
            throw new InvalidOperationException("That username is already taken.");
        }

        var email = string.IsNullOrWhiteSpace(request.Email) ? null : request.Email.Trim();
        if (email is not null)
        {
            var normalizedEmail = email.ToLower();
            if (await dbContext.Users.AnyAsync(user => user.Email != null && user.Email.ToLower() == normalizedEmail, cancellationToken))
            {
                throw new InvalidOperationException("That email address is already in use.");
            }
        }

        var created = new User
        {
            Username = username,
            Email = email,
            Role = request.Role,
            IsActive = true,
            PasswordHash = PasswordHasher.Hash(request.Password!)
        };

        dbContext.Users.Add(created);
        await dbContext.SaveChangesAsync(cancellationToken);

        return ToDto(created);
    }

public async Task<UserDto> UpdateAsync(int id, int currentUserId, UpdateUserRequest request, CancellationToken cancellationToken = default)
    {
        var user = await dbContext.Users.FirstOrDefaultAsync(candidate => candidate.Id == id, cancellationToken)
            ?? throw new KeyNotFoundException($"User {id} was not found.");

        var losingAdmin = user.Role == UserRole.Admin && (request.Role != UserRole.Admin || !request.IsActive);
        if (losingAdmin && await IsLastActiveAdminAsync(user.Id, cancellationToken))
        {
            throw new InvalidOperationException("The last administrator cannot be demoted or deactivated.");
        }

        if (user.Id == currentUserId && !request.IsActive)
        {
            throw new InvalidOperationException("You cannot deactivate your own account.");
        }

        user.Email = string.IsNullOrWhiteSpace(request.Email) ? null : request.Email.Trim();
        user.Role = request.Role;
        user.IsActive = request.IsActive;

        await dbContext.SaveChangesAsync(cancellationToken);
        return ToDto(user);
    }

    public async Task ResetPasswordAsync(int id, string password, CancellationToken cancellationToken = default)
    {
        if ((password ?? string.Empty).Length < MinimumPasswordLength)
        {
            throw new InvalidOperationException($"The password must be at least {MinimumPasswordLength} characters.");
        }

        var user = await dbContext.Users.FirstOrDefaultAsync(candidate => candidate.Id == id, cancellationToken)
            ?? throw new KeyNotFoundException($"User {id} was not found.");

        user.PasswordHash = PasswordHasher.Hash(password!);
        await dbContext.SaveChangesAsync(cancellationToken);
    }

    public async Task<bool> DeleteAsync(int id, int currentUserId, CancellationToken cancellationToken = default)
    {
        if (id == currentUserId)
        {
            throw new InvalidOperationException("You cannot delete your own account.");
        }

        var user = await dbContext.Users.FirstOrDefaultAsync(candidate => candidate.Id == id, cancellationToken);
        if (user is null)
        {
            return false;
        }

        if (user.Role == UserRole.Admin && await IsLastActiveAdminAsync(user.Id, cancellationToken))
        {
            throw new InvalidOperationException("The last administrator cannot be deleted.");
        }

        dbContext.Users.Remove(user);
        await dbContext.SaveChangesAsync(cancellationToken);
        return true;
    }

    private async Task<bool> IsLastActiveAdminAsync(int excludingUserId, CancellationToken cancellationToken) =>
        !await dbContext.Users.AnyAsync(
            user => user.Id != excludingUserId && user.Role == UserRole.Admin && user.IsActive,
            cancellationToken);

    private static UserDto ToDto(User user) => new(
        user.Id,
        user.Username,
        user.Email,
        user.Role,
        user.IsActive,
        user.CreatedUtc,
        user.LastLoginUtc);
}

