public async Task<int> GenerateFixturesAsync(int tournamentId, GenerateFixturesRequest request, CancellationToken cancellationToken = default)
    {
        var tournament = await dbContext.Tournaments
            .Include(candidate => candidate.Groups)
            .Include(candidate => candidate.Teams)
            .Include(candidate => candidate.Matches)
            .FirstOrDefaultAsync(candidate => candidate.Id == tournamentId, cancellationToken)
            ?? throw new KeyNotFoundException($"Tournament {tournamentId} was not found.");

        if (request.ReplaceExisting)
        {
            var doomed = tournament.Matches
                .Where(match => (request.IncludeGroupStage && match.Stage == MatchStage.Group)
                    || (request.IncludeKnockoutStage && match.Stage != MatchStage.Group))
                .ToList();

            dbContext.Matches.RemoveRange(doomed);
        }
        else if (tournament.Matches.Count > 0)
        {
            throw new InvalidOperationException("Fixtures already exist. Enable 'replace existing' to regenerate them.");
        }

        var generated = new List<Match>();

        if (request.IncludeGroupStage && tournament.Format != TournamentFormat.KnockoutOnly)
        {
            if (tournament.Format == TournamentFormat.League || tournament.Groups.Count == 0)
            {
                // No groups configured, so treat the whole field as one league.
                var placeholder = new TournamentGroup { Id = 0, TournamentId = tournament.Id, Name = "League" };
                generated.AddRange(FixtureGenerator
                    .GenerateGroupFixtures(tournament, placeholder, tournament.Teams.OrderBy(team => team.SortOrder).ToList())
                    .Select(match =>
                    {
                        match.GroupId = null;
                        return match;
                    }));
            }
            else
            {
                foreach (var group in tournament.Groups.OrderBy(group => group.SortOrder))
                {
                    var groupTeams = tournament.Teams
                        .Where(team => team.GroupId == group.Id)
                        .OrderBy(team => team.SortOrder)
                        .ThenBy(team => team.Name)
                        .ToList();

                    generated.AddRange(FixtureGenerator.GenerateGroupFixtures(tournament, group, groupTeams));
                }
            }
        }

        if (request.IncludeKnockoutStage && tournament.Format != TournamentFormat.GroupsOnly)
        {
            var slots = tournament.Format == TournamentFormat.KnockoutOnly
                ? tournament.Teams.Count
                : Math.Max(tournament.Groups.Count, 1) * tournament.TeamsAdvancingPerGroup;

            generated.AddRange(FixtureGenerator.GenerateKnockoutBracket(tournament, slots));
        }

        AssignKickoffTimes(tournament, generated);

        dbContext.Matches.AddRange(generated);
        await dbContext.SaveChangesAsync(cancellationToken);
        return generated.Count;
    }

private static void AssignKickoffTimes(Tournament tournament, IReadOnlyCollection<Match> matches)
    {
        if (tournament.TournamentDateUtc is null)
        {
            return;
        }

        var slotDuration = tournament.PeriodDurationMinutes + (tournament.MatchIntervalMinutes ?? 0);
        foreach (var roundMatches in matches
            .Where(match => match.Stage == MatchStage.Group)
            .GroupBy(match => match.Round))
        {
            var ordered = roundMatches.ToList();
            for (var index = 0; index < ordered.Count; index++)
            {
                var slot = index / Math.Max(1, tournament.MatchesPerTimeSlot);
                ordered[index].KickoffUtc = tournament.TournamentDateUtc.Value
                    .AddMinutes(((ordered[0].Round - 1) + slot) * slotDuration);
            }
        }
    }

    private async Task<string> EnsureUniqueSlugAsync(string slug, CancellationToken cancellationToken)
    {
        var candidate = slug;
        var suffix = 2;

        while (await dbContext.Tournaments.AnyAsync(tournament => tournament.Slug == candidate, cancellationToken))
        {
            candidate = $"{slug}-{suffix++}";
        }

        return candidate;
    }

    public static string Slugify(string value)
    {
        var builder = new System.Text.StringBuilder();
        var previousWasDash = false;

        foreach (var character in value.Trim().ToLowerInvariant())
        {
            if (char.IsLetterOrDigit(character))
            {
                builder.Append(character);
                previousWasDash = false;
            }
            else if (!previousWasDash && builder.Length > 0)
            {
                builder.Append('-');
                previousWasDash = true;
            }
        }

        return builder.ToString().Trim('-') is { Length: > 0 } slug ? slug : "tournament";
    }
}

public class Tournament
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;

    /// <summary>URL-friendly identifier used by the public frontend, e.g. "liga-cup-2026".</summary>
    public string Slug { get; set; } = string.Empty;

    public string? Description { get; set; }
    public string? Rules { get; set; }
    public DateTime? TournamentDateUtc { get; set; }
    public int Season { get; set; }
    public TournamentFormat Format { get; set; } = TournamentFormat.League;
    public TournamentStatus Status { get; set; } = TournamentStatus.Draft;

    public int PointsForWin { get; set; } = 3;
    public int PointsForDraw { get; set; } = 1;
    public int PointsForLoss { get; set; }

    /// <summary>Each team plays every other team in its group this many times.</summary>
    public int GroupRounds { get; set; } = 1;

    /// <summary>How many teams from each group progress to the knockout stage.</summary>
    public int TeamsAdvancingPerGroup { get; set; } = 2;

    /// <summary>When true, the best third-placed teams fill the remaining knockout slots.</summary>
    public bool IncludeBestThirdPlaced { get; set; }

    public bool HasThirdPlacePlayOff { get; set; }

    /// <summary>When false the app runs in a lightweight teams-and-scores mode with no squads.</summary>
    public bool TrackPlayers { get; set; }
    public PlayerRegistrationMode PlayerRegistrationMode { get; set; } = PlayerRegistrationMode.NamesAndNumbers;

    /// <summary>When false, cards are not recorded and disciplinary tiebreakers are skipped.</summary>
    public bool TrackCards { get; set; }

    /// <summary>Halves by default. Set to 1 for a single straight period, or 4 for quarters.</summary>
    public int PeriodCount { get; set; } = 2;

    public int PeriodDurationMinutes { get; set; } = 45;

    /// <summary>Shown as a countdown during the interval. Does not affect the match clock.</summary>
    public int BreakDurationMinutes { get; set; } = 15;

    /// <summary>Optional pause between scheduled matches, in minutes.</summary>
    public int? MatchIntervalMinutes { get; set; }

    /// <summary>How many matches start together in each schedule slot.</summary>
    public int MatchesPerTimeSlot { get; set; } = 4;

    /// <summary>When false the organiser records scores without any running clock.</summary>
    public bool TrackMatchClock { get; set; } = true;

    /// <summary>Allows the clock to be stopped inside a period for injuries or timeouts.</summary>
    public bool AllowTimeouts { get; set; }

    /// <summary>When true the clock keeps counting past the period as 45+2 rather than stopping.</summary>
    public bool UseStoppageTime { get; set; } = true;

    public int TotalDurationMinutes => Math.Max(1, PeriodCount) * Math.Max(1, PeriodDurationMinutes);

    /// <summary>Tiebreaker rules serialised in priority order, applied after points.</summary>
    public string TiebreakerOrder { get; set; } = "GoalDifference,GoalsScored,Lottery";

    public DateTime CreatedUtc { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedUtc { get; set; } = DateTime.UtcNow;

    public ICollection<Team> Teams { get; set; } = [];
    public ICollection<TournamentGroup> Groups { get; set; } = [];
    public ICollection<Match> Matches { get; set; } = [];

    public IReadOnlyList<TiebreakerRule> GetTiebreakers()
    {
        if (string.IsNullOrWhiteSpace(TiebreakerOrder))
        {
            return [TiebreakerRule.GoalDifference, TiebreakerRule.GoalsScored, TiebreakerRule.Lottery];
        }

        return TiebreakerOrder

.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(value => Enum.TryParse<TiebreakerRule>(value, ignoreCase: true, out var rule) ? rule : (TiebreakerRule?)null)
            .Where(rule => rule.HasValue)
            .Select(rule => rule!.Value)
            .ToList();
    }
}

