/// Ordered criteria used to separate teams that are level in a group table.
/// </summary>

using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;

namespace LigaCup.Domain.Scheduling;

/// <summary>
/// Builds the fixture list for a tournament: a round robin inside every group and,
/// when the format calls for it, an empty knockout bracket wired up with placeholders.
/// </summary>
public static class FixtureGenerator
{
    public static List<Match> GenerateGroupFixtures(Tournament tournament, TournamentGroup group, IReadOnlyList<Team> teams)
    {
        var fixtures = new List<Match>();
        if (teams.Count < 2)
        {
            return fixtures;
        }

        var rounds = Math.Max(1, tournament.GroupRounds);

        var legFixtures = BuildSingleRoundRobin(teams);
        var matchdaysPerLeg = legFixtures.Count == 0 ? 0 : legFixtures.Max(fixture => fixture.Matchday);

        for (var round = 0; round < rounds; round++)
        {
            foreach (var (home, away, matchday) in legFixtures)
            {
                // Alternate home advantage on every return leg.
                var swap = round % 2 == 1;

                fixtures.Add(new Match
                {
                    TournamentId = tournament.Id,
                    GroupId = group.Id,
                    Stage = MatchStage.Group,
                    Round = (round * matchdaysPerLeg) + matchday,
                    HomeTeamId = swap ? away.Id : home.Id,
                    AwayTeamId = swap ? home.Id : away.Id,
                    Status = MatchStatus.Scheduled
                });
            }
        }

        return fixtures;
    }

    /// <summary>
    /// Circle method round robin. A bye team is added when the count is odd so that
    /// every real team sits out exactly one matchday.
    /// </summary>

private static List<(Team Home, Team Away, int Matchday)> BuildSingleRoundRobin(IReadOnlyList<Team> teams)
    {
        var participants = teams.ToList();
        Team? bye = null;

        if (participants.Count % 2 == 1)
        {
            bye = new Team { Id = -1, Name = "BYE" };
            participants.Add(bye);
        }

        var count = participants.Count;
        var matchdays = count - 1;
        var half = count / 2;
        var fixtures = new List<(Team, Team, int)>();

        var rotation = participants.Skip(1).ToList();

        for (var matchday = 0; matchday < matchdays; matchday++)
        {
            var roundTeams = new List<Team> { participants[0] };
            roundTeams.AddRange(rotation);

            for (var index = 0; index < half; index++)
            {
                var home = roundTeams[index];
                var away = roundTeams[count - 1 - index];

                if (ReferenceEquals(home, bye) || ReferenceEquals(away, bye))
                {
                    continue;
                }

                // Flip the pairing on alternating matchdays to balance home and away games.
                if (matchday % 2 == 1 && index == 0)
                {
                    (home, away) = (away, home);
                }

                fixtures.Add((home, away, matchday + 1));
            }

            var last = rotation[^1];
            rotation.RemoveAt(rotation.Count - 1);
            rotation.Insert(0, last);
        }

        return fixtures;
    }

    /// <summary>
    /// Creates the knockout ties as empty placeholder matches. Teams are filled in later,
    /// either automatically from the final group tables or manually by the organiser.
    /// </summary>

public static List<Match> GenerateKnockoutBracket(Tournament tournament, int slots)
    {
        var fixtures = new List<Match>();
        var bracketSize = NormaliseBracketSize(slots);

        if (bracketSize < 2)
        {
            return fixtures;
        }

        var stage = StageForSize(bracketSize);
        var tieNumber = 1;
        var previousLabels = new List<string>();

        var tiesInRound = bracketSize / 2;
        for (var tie = 0; tie < tiesInRound; tie++)
        {
            fixtures.Add(new Match
            {
                TournamentId = tournament.Id,
                Stage = stage,
                Round = tieNumber,
                HomePlaceholder = $"Seed {(tie * 2) + 1}",
                AwayPlaceholder = $"Seed {(tie * 2) + 2}",
                Status = MatchStatus.Scheduled
            });

            previousLabels.Add($"{StageLabel(stage)}{tieNumber}");
            tieNumber++;
        }

        var remaining = tiesInRound;
        while (remaining > 1)
        {
            remaining /= 2;
            stage = StageForSize(remaining * 2);
            var currentLabels = new List<string>();

            for (var tie = 0; tie < remaining; tie++)
            {
                fixtures.Add(new Match
                {
                    TournamentId = tournament.Id,
                    Stage = stage,
                    Round = tieNumber,
                    HomePlaceholder = $"Winner {previousLabels[tie * 2]}",
                    AwayPlaceholder = $"Winner {previousLabels[(tie * 2) + 1]}",
                    Status = MatchStatus.Scheduled
                });

                currentLabels.Add($"{StageLabel(stage)}{tieNumber}");
                tieNumber++;
            }

            previousLabels = currentLabels;
        }

        if (tournament.HasThirdPlacePlayOff && fixtures.Any(fixture => fixture.Stage == MatchStage.SemiFinal))
        {
            var semiFinals = fixtures.Where(fixture => fixture.Stage == MatchStage.SemiFinal).ToList();

            fixtures.Add(new Match
            {
                TournamentId = tournament.Id,
                Stage = MatchStage.ThirdPlacePlayOff,
                Round = tieNumber,
                HomePlaceholder = $"Loser SF{semiFinals[0].Round}",
                AwayPlaceholder = $"Loser SF{semiFinals[1].Round}",
                Status = MatchStatus.Scheduled
            });
        }

        return fixtures;
    }

    /// <summary>Rounds the slot count down to the nearest power of two, capped at 32.</summary>

public static int NormaliseBracketSize(int slots)
    {
        if (slots < 2)
        {
            return 0;
        }

        var size = 2;
        while (size * 2 <= Math.Min(slots, 32))
        {
            size *= 2;
        }

        return size;
    }

    /// <summary>Stable identifier for a tie, used to wire winners into the next round.</summary>
    public static string TieLabel(MatchStage stage, int round) => $"{StageLabel(stage)}{round}";

    private static MatchStage StageForSize(int size) => size switch
    {
        >= 32 => MatchStage.RoundOf32,
        16 => MatchStage.RoundOf16,
        8 => MatchStage.QuarterFinal,
        4 => MatchStage.SemiFinal,
        _ => MatchStage.Final
    };

    public static string StageLabel(MatchStage stage) => stage switch
    {
        MatchStage.RoundOf32 => "R32-",
        MatchStage.RoundOf16 => "R16-",
        MatchStage.QuarterFinal => "QF",
        MatchStage.SemiFinal => "SF",
        MatchStage.ThirdPlacePlayOff => "3RD",
        _ => "F"
    };
}

using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;

namespace LigaCup.Domain.Standings;

public class StandingRow
{
    public int Position { get; set; }
    public int TeamId { get; set; }
    public string TeamName { get; set; } = string.Empty;
    public string? ShortName { get; set; }
    public string? LogoUrl { get; set; }
    public int? GroupId { get; set; }
    public string? GroupName { get; set; }

    public int Played { get; set; }
    public int Won { get; set; }
    public int Drawn { get; set; }
    public int Lost { get; set; }
    public int GoalsFor { get; set; }
    public int GoalsAgainst { get; set; }
    public int GoalDifference => GoalsFor - GoalsAgainst;
    public int Points { get; set; }
    public int YellowCards { get; set; }
    public int RedCards { get; set; }

    /// <summary>Most recent results first, each entry being W, D or L.</summary>
    public List<string> Form { get; set; } = [];

    /// <summary>True when the team currently occupies a qualifying position.</summary>
    public bool IsQualifying { get; set; }
}

/// <summary>
/// Builds group tables from finished matches using standard football rules.
/// </summary>
public static class StandingsCalculator
{

public static IReadOnlyList<StandingRow> Calculate(
        Tournament tournament,
        IReadOnlyCollection<Team> teams,
        IReadOnlyCollection<Match> matches,
        int? groupId = null)
    {
        var groupTeams = groupId is null
            ? teams
            : teams.Where(team => team.GroupId == groupId).ToList();

        var relevantMatches = matches
            .Where(match => match.CountsTowardsTable)
            .Where(match => groupId is null || match.GroupId == groupId)
            .Where(match => match.HomeTeamId is not null && match.AwayTeamId is not null)
            .OrderBy(match => match.KickoffUtc ?? DateTime.MaxValue)
            .ThenBy(match => match.Round)
            .ToList();

        var rows = groupTeams.ToDictionary(
            team => team.Id,
            team => new StandingRow
            {
                TeamId = team.Id,
                TeamName = team.Name,
                ShortName = team.ShortName,
                LogoUrl = team.LogoUrl,
                GroupId = team.GroupId,
                GroupName = team.Group?.Name,
                Points = team.PointsAdjustment
            });

        foreach (var match in relevantMatches)
        {
            ApplyResult(tournament, rows, match);
        }

        foreach (var row in rows.Values)
        {
            // Form reads newest first, so reverse the chronological order built above.
            row.Form.Reverse();
            if (row.Form.Count > 5)
            {
                row.Form = row.Form.Take(5).ToList();
            }
        }

        var ordered = Rank(rows.Values.ToList(), relevantMatches, tournament.GetTiebreakers(), ruleIndex: 0);

        for (var index = 0; index < ordered.Count; index++)
        {
            ordered[index].Position = index + 1;
            ordered[index].IsQualifying = tournament.Format is not (TournamentFormat.GroupsOnly or TournamentFormat.League)
                && index < tournament.TeamsAdvancingPerGroup;
        }

        return ordered;
    }

private static void ApplyResult(Tournament tournament, Dictionary<int, StandingRow> rows, Match match)
    {
        if (!rows.TryGetValue(match.HomeTeamId!.Value, out var home) ||
            !rows.TryGetValue(match.AwayTeamId!.Value, out var away))
        {
            return;
        }

        home.Played++;
        away.Played++;
        home.GoalsFor += match.HomeScore;
        home.GoalsAgainst += match.AwayScore;
        away.GoalsFor += match.AwayScore;
        away.GoalsAgainst += match.HomeScore;

        if (match.HomeScore > match.AwayScore)
        {
            home.Won++;
            away.Lost++;
            home.Points += tournament.PointsForWin;
            away.Points += tournament.PointsForLoss;
            home.Form.Add("W");
            away.Form.Add("L");
        }
        else if (match.HomeScore < match.AwayScore)
        {
            away.Won++;
            home.Lost++;
            away.Points += tournament.PointsForWin;
            home.Points += tournament.PointsForLoss;
            away.Form.Add("W");
            home.Form.Add("L");
        }
        else
        {
            home.Drawn++;
            away.Drawn++;
            home.Points += tournament.PointsForDraw;
            away.Points += tournament.PointsForDraw;
            home.Form.Add("D");
            away.Form.Add("D");
        }

        foreach (var matchEvent in match.Events)
        {
            if (!rows.TryGetValue(matchEvent.TeamId, out var row))
            {
                continue;
            }

            if (matchEvent.Type == MatchEventType.YellowCard)
            {
                row.YellowCards++;
            }
            else if (matchEvent.Type == MatchEventType.RedCard)
            {
                row.RedCards++;
            }
        }
    }

    /// <summary>
    /// Orders rows by points, then walks the configured tiebreakers to split teams that remain level.
    /// Head-to-head rules are evaluated as a mini-league between the tied teams only.
    /// </summary>

private static List<StandingRow> Rank(
        List<StandingRow> rows,
        IReadOnlyCollection<Match> matches,
        IReadOnlyList<TiebreakerRule> tiebreakers,
        int ruleIndex)
    {
        if (rows.Count <= 1)
        {
            return rows;
        }

        if (ruleIndex == 0)
        {
            return rows
                .GroupBy(row => row.Points)
                .OrderByDescending(group => group.Key)
                .SelectMany(group => Rank(group.ToList(), matches, tiebreakers, 1))
                .ToList();
        }

        var rule = ruleIndex <= tiebreakers.Count ? tiebreakers[ruleIndex - 1] : (TiebreakerRule?)null;
        if (rule is null)
        {
            return rows.OrderBy(row => row.TeamName, StringComparer.OrdinalIgnoreCase).ToList();
        }

        if (rule == TiebreakerRule.Lottery)
        {
            return rows;
        }

        var keys = BuildKeys(rows, matches, rule.Value);

        return rows
            .GroupBy(row => keys[row.TeamId])
            .OrderByDescending(group => group.Key)
            .SelectMany(group => Rank(group.ToList(), matches, tiebreakers, ruleIndex + 1))
            .ToList();
    }

    /// <summary>Produces a comparable score per team where a higher value always ranks better.</summary>

private static Dictionary<int, long> BuildKeys(
        List<StandingRow> rows,
        IReadOnlyCollection<Match> matches,
        TiebreakerRule rule)
    {
        var keys = new Dictionary<int, long>();

        if (rule is TiebreakerRule.HeadToHeadPoints
            or TiebreakerRule.HeadToHeadGoalDifference
            or TiebreakerRule.HeadToHeadGoalsScored)
        {
            var tiedTeamIds = rows.Select(row => row.TeamId).ToHashSet();
            var miniLeague = matches
                .Where(match => tiedTeamIds.Contains(match.HomeTeamId!.Value) && tiedTeamIds.Contains(match.AwayTeamId!.Value))
                .ToList();

            foreach (var row in rows)
            {
                var points = 0;
                var scored = 0;
                var conceded = 0;

                foreach (var match in miniLeague)
                {
                    var isHome = match.HomeTeamId == row.TeamId;
                    var isAway = match.AwayTeamId == row.TeamId;
                    if (!isHome && !isAway)
                    {
                        continue;
                    }

                    var teamGoals = isHome ? match.HomeScore : match.AwayScore;
                    var opponentGoals = isHome ? match.AwayScore : match.HomeScore;

                    scored += teamGoals;
                    conceded += opponentGoals;
                    points += teamGoals > opponentGoals ? 3 : teamGoals == opponentGoals ? 1 : 0;
                }

                keys[row.TeamId] = rule switch
                {
                    TiebreakerRule.HeadToHeadPoints => points,
                    TiebreakerRule.HeadToHeadGoalDifference => scored - conceded,
                    _ => scored
                };
            }

            return keys;
        }

        foreach (var row in rows)
        {
            keys[row.TeamId] = rule switch
            {
                TiebreakerRule.GoalDifference => row.GoalDifference,
                TiebreakerRule.GoalsScored => row.GoalsFor,
                TiebreakerRule.GoalsConceded => -row.GoalsAgainst,
                TiebreakerRule.Wins => row.Won,
                TiebreakerRule.DisciplinaryPoints => -((row.YellowCards * 1L) + (row.RedCards * 3L)),
                TiebreakerRule.TeamName => AlphabeticalKey(row.TeamName),
                _ => 0
            };
        }

        return keys;
    }

    /// <summary>Negated so that names earlier in the alphabet produce a higher ranking key.</summary>

private static long AlphabeticalKey(string name)
    {
        var key = 0L;
        var normalized = name.ToUpperInvariant();

        for (var index = 0; index < 6; index++)
        {
            var character = index < normalized.Length ? normalized[index] : ' ';
            key = (key * 128) + Math.Min(character, (char)127);
        }

        return -key;
    }
}

using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;

namespace LigaCup.Domain.Timing;

/// <summary>
/// A snapshot of the match clock. <see cref="DisplayMinute"/> is the number shown on screen,
/// and <see cref="StoppageShown"/> is the "+2" part once a period runs past its regulation length.
/// </summary>
public record MatchClockState(
    int Period,
    int MinuteInPeriod,
    int DisplayMinute,
    int? StoppageShown,
    bool IsRunning,
    int ElapsedSeconds);

/// <summary>
/// Works out the match clock from banked play time plus the current running spell.
/// Pauses and the half-time interval do not count, which is what makes this different
/// from simply subtracting the kickoff time from the current time.
/// </summary>
public static class MatchClock
{
    public static MatchClockState Calculate(Tournament tournament, Match match, DateTime nowUtc)
    {
        var periodDuration = Math.Max(1, tournament.PeriodDurationMinutes);
        var period = Math.Clamp(match.CurrentPeriod, 1, Math.Max(1, tournament.PeriodCount));

        var isRunning = match.Status == MatchStatus.Live && match.ClockStartedUtc is not null;

        var elapsedSeconds = match.PeriodElapsedSeconds;
        if (isRunning)
        {
            elapsedSeconds += (int)Math.Max(0, (nowUtc - match.ClockStartedUtc!.Value).TotalSeconds);
        }

        var minuteInPeriod = elapsedSeconds / 60;

        if (!tournament.UseStoppageTime)
        {
            minuteInPeriod = Math.Min(minuteInPeriod, periodDuration);
        }

        var regulationEnd = period * periodDuration;
        var displayMinute = ((period - 1) * periodDuration) + minuteInPeriod;

        int? stoppageShown = displayMinute > regulationEnd ? displayMinute - regulationEnd : null;

        return new MatchClockState(
            period,
            minuteInPeriod,
            displayMinute,
            stoppageShown,
            isRunning,
            elapsedSeconds);
    }

    /// <summary>
    /// Applies a status change to the clock fields. Returns the match so callers can chain,
    /// and keeps every transition rule in one place rather than scattered across the service.
    /// </summary>

public static void ApplyStatusChange(Tournament tournament, Match match, MatchStatus status, DateTime nowUtc)
    {
        var previous = match.Status;

        switch (status)
        {
            case MatchStatus.Live:
                if (previous == MatchStatus.HalfTime)
                {
                    // Coming back from the interval starts the next period from zero.
                    match.CurrentPeriod = Math.Min(match.CurrentPeriod + 1, Math.Max(1, tournament.PeriodCount));
                    match.PeriodElapsedSeconds = 0;
                    match.StoppageMinutes = 0;
                }

                match.StartedUtc ??= nowUtc;
                match.ClockStartedUtc = nowUtc;
                match.FinishedUtc = null;
                break;

            case MatchStatus.HalfTime:
            case MatchStatus.Paused:
                BankRunningTime(match, nowUtc);
                match.ClockStartedUtc = null;
                break;

            case MatchStatus.Finished:
                BankRunningTime(match, nowUtc);
                match.ClockStartedUtc = null;
                match.FinishedUtc = nowUtc;
                break;

            case MatchStatus.Scheduled:
                match.StartedUtc = null;
                match.ClockStartedUtc = null;
                match.FinishedUtc = null;
                match.CurrentPeriod = 1;
                match.PeriodElapsedSeconds = 0;
                match.StoppageMinutes = 0;
                break;

            default:
                BankRunningTime(match, nowUtc);
                match.ClockStartedUtc = null;
                match.FinishedUtc = null;
                break;
        }

        match.Status = status;
    }

    private static void BankRunningTime(Match match, DateTime nowUtc)
    {
        if (match.ClockStartedUtc is null)
        {
            return;
        }

        match.PeriodElapsedSeconds += (int)Math.Max(0, (nowUtc - match.ClockStartedUtc.Value).TotalSeconds);
    }
}

using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;
using LigaCup.Domain.Timing;

namespace LigaCup.Domain.Tests;

public class MatchClockTests
{
    private static readonly DateTime Kickoff = new(2026, 6, 1, 12, 0, 0, DateTimeKind.Utc);

    private static Tournament BuildTournament(
        int periods = 2,
        int periodMinutes = 45,
        bool stoppage = true) => new()
        {
            Id = 1,
            PeriodCount = periods,
            PeriodDurationMinutes = periodMinutes,
            UseStoppageTime = stoppage,
            TrackMatchClock = true
        };

    private static Match BuildMatch() => new()
    {
        Id = 1,
        TournamentId = 1,
        Status = MatchStatus.Scheduled
    };

    [Fact]
    public void ClockStartsWhenTheMatchGoesLive()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(10));

        Assert.Equal(Kickoff, match.StartedUtc);
        Assert.True(state.IsRunning);
        Assert.Equal(10, state.DisplayMinute);
        Assert.Equal(1, state.Period);
    }

    [Fact]
    public void ClockDoesNotRunBeforeKickoff()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(30));

        Assert.False(state.IsRunning);
        Assert.Equal(0, state.DisplayMinute);
    }

    [Fact]
    public void HalfTimeStopsTheClock()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.HalfTime, Kickoff.AddMinutes(45));

        // Fifteen minutes of interval must not advance the clock.
        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(60));

        Assert.False(state.IsRunning);
        Assert.Equal(45, state.DisplayMinute);
    }

    [Fact]

public void SecondHalfResumesAtTheStartOfTheNextPeriod()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.HalfTime, Kickoff.AddMinutes(47));
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff.AddMinutes(62));

        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(72));

        Assert.Equal(2, state.Period);
        Assert.Equal(10, state.MinuteInPeriod);
        Assert.Equal(55, state.DisplayMinute);
    }

    [Fact]
    public void APauseInsideAPeriodFreezesAndThenResumesTheClock()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Paused, Kickoff.AddMinutes(20));

        Assert.Equal(20, MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(25)).DisplayMinute);

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff.AddMinutes(25));
        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(30));

        // Five minutes of stoppage were paused, so 30 minutes of real time is 25 of play.
        Assert.Equal(1, state.Period);
        Assert.Equal(25, state.DisplayMinute);
    }

    [Fact]
    public void PlayPastTheEndOfAPeriodIsShownAsAddedTime()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(47));

        Assert.Equal(47, state.DisplayMinute);
        Assert.Equal(2, state.StoppageShown);
    }

    [Fact]
    public void StoppageTimeCanBeSwitchedOffSoTheClockStopsAtTheWhistle()
    {
        var tournament = BuildTournament(stoppage: false);
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(52));

        Assert.Equal(45, state.DisplayMinute);
        Assert.Null(state.StoppageShown);
    }

    [Fact]
    public void ShorterFormatsUseTheirOwnPeriodLength()
    {
        var tournament = BuildTournament(periods: 2, periodMinutes: 10);
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.HalfTime, Kickoff.AddMinutes(10));
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff.AddMinutes(12));

        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(15));

        Assert.Equal(2, state.Period);
        Assert.Equal(13, state.DisplayMinute);
        Assert.Equal(20, tournament.TotalDurationMinutes);
    }

    [Fact]

public void ASinglePeriodFormatNeverAdvancesPastPeriodOne()
    {
        var tournament = BuildTournament(periods: 1, periodMinutes: 20);
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.HalfTime, Kickoff.AddMinutes(20));
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff.AddMinutes(21));

        Assert.Equal(1, MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(22)).Period);
    }

    [Fact]
    public void FinishingBanksTheTimeAndStopsTheClock()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Finished, Kickoff.AddMinutes(48));

        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(200));

        Assert.False(state.IsRunning);
        Assert.Equal(48, state.DisplayMinute);
        Assert.Equal(Kickoff.AddMinutes(48), match.FinishedUtc);
    }

    [Fact]
    public void ResettingToScheduledClearsTheClock()
    {
        var tournament = BuildTournament();
        var match = BuildMatch();

        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff);
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.HalfTime, Kickoff.AddMinutes(45));
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Live, Kickoff.AddMinutes(60));
        MatchClock.ApplyStatusChange(tournament, match, MatchStatus.Scheduled, Kickoff.AddMinutes(70));

        var state = MatchClock.Calculate(tournament, match, Kickoff.AddMinutes(90));

        Assert.Null(match.StartedUtc);
        Assert.Equal(1, state.Period);
        Assert.Equal(0, state.DisplayMinute);
    }
}

using LigaCup.Domain.Entities;
using LigaCup.Domain.Enums;
using LigaCup.Domain.Scheduling;
using LigaCup.Domain.Standings;

namespace LigaCup.Domain.Tests;

public class StandingsCalculatorTests
{
    private static Tournament BuildTournament(string tiebreakers = "GoalDifference,GoalsScored,TeamName") => new()
    {
        Id = 1,
        Name = "Liga Cup",
        PointsForWin = 3,
        PointsForDraw = 1,
        PointsForLoss = 0,
        TeamsAdvancingPerGroup = 2,
        Format = TournamentFormat.GroupsThenKnockout,
        TiebreakerOrder = tiebreakers
    };

    private static List<Team> BuildTeams(params string[] names) =>
        names.Select((name, index) => new Team { Id = index + 1, TournamentId = 1, GroupId = 1, Name = name }).ToList();

    private static Match Result(int homeTeamId, int awayTeamId, int homeScore, int awayScore) => new()
    {
        Id = (homeTeamId * 100) + awayTeamId,
        TournamentId = 1,
        GroupId = 1,
        Stage = MatchStage.Group,
        Status = MatchStatus.Finished,
        HomeTeamId = homeTeamId,
        AwayTeamId = awayTeamId,
        HomeScore = homeScore,
        AwayScore = awayScore
    };

    [Fact]
    public void AwardsThreePointsForAWinAndOneForADraw()
    {
        var teams = BuildTeams("Alpha", "Beta", "Gamma");
        var matches = new List<Match> { Result(1, 2, 2, 0), Result(2, 3, 1, 1) };

        var table = StandingsCalculator.Calculate(BuildTournament(), teams, matches, groupId: 1);

        Assert.Equal("Alpha", table[0].TeamName);
        Assert.Equal(3, table[0].Points);
        Assert.Equal(1, table[0].Won);
        Assert.Equal(1, table.Single(row => row.TeamName == "Beta").Points);
        Assert.Equal(1, table.Single(row => row.TeamName == "Gamma").Points);
    }

    [Fact]
    public void IgnoresMatchesThatHaveNotFinished()
    {
        var teams = BuildTeams("Alpha", "Beta");
        var live = Result(1, 2, 3, 0);
        live.Status = MatchStatus.Live;

        var table = StandingsCalculator.Calculate(BuildTournament(), teams, [live], groupId: 1);

        Assert.All(table, row => Assert.Equal(0, row.Played));
        Assert.All(table, row => Assert.Equal(0, row.Points));
    }

    [Fact]

public void SeparatesLevelTeamsOnGoalDifferenceThenGoalsScored()
    {
        var teams = BuildTeams("Alpha", "Beta", "Gamma", "Delta");

        // Alpha and Beta both finish on 3 points. Beta has the better goal difference.
        var matches = new List<Match>
        {
            Result(1, 3, 1, 0),
            Result(2, 4, 4, 0)
        };

        var table = StandingsCalculator.Calculate(BuildTournament(), teams, matches, groupId: 1);

        Assert.Equal("Beta", table[0].TeamName);
        Assert.Equal(4, table[0].GoalDifference);
        Assert.Equal("Alpha", table[1].TeamName);
    }

    [Fact]
    public void HeadToHeadOnlyComparesTheTeamsThatAreStillLevel()
    {
        var teams = BuildTeams("Alpha", "Beta", "Gamma");

        // Alpha and Beta both take 3 points with an identical goal difference, but Beta beat Alpha.
        var matches = new List<Match>
        {
            Result(2, 1, 1, 0),
            Result(1, 3, 1, 0)
        };

        var tournament = BuildTournament("HeadToHeadPoints,GoalDifference,TeamName");
        var table = StandingsCalculator.Calculate(tournament, teams, matches, groupId: 1);

        Assert.Equal("Beta", table[0].TeamName);
        Assert.Equal("Alpha", table[1].TeamName);
    }

    [Fact]
    public void AppliesOrganiserPointsDeductions()
    {
        var teams = BuildTeams("Alpha", "Beta");
        teams[0].PointsAdjustment = -3;

        var table = StandingsCalculator.Calculate(BuildTournament(), teams, [Result(1, 2, 1, 0)], groupId: 1);

        // The win is wiped out by the deduction, leaving both teams level on nothing.
        Assert.Equal(0, table.Single(row => row.TeamName == "Alpha").Points);
        Assert.Equal(0, table.Single(row => row.TeamName == "Beta").Points);
        Assert.Equal(1, table.Single(row => row.TeamName == "Alpha").Won);
    }

    [Fact]
    public void MarksTheQualifyingPositions()
    {
        var teams = BuildTeams("Alpha", "Beta", "Gamma", "Delta");
        var table = StandingsCalculator.Calculate(BuildTournament(), teams, [Result(1, 2, 1, 0)], groupId: 1);

        Assert.True(table[0].IsQualifying);
        Assert.True(table[1].IsQualifying);
        Assert.False(table[2].IsQualifying);
    }

    [Fact]
    public void FormShowsTheMostRecentResultFirst()
    {
        var teams = BuildTeams("Alpha", "Beta", "Gamma");

        var win = Result(1, 2, 2, 0);
        win.KickoffUtc = new DateTime(2026, 6, 1, 12, 0, 0, DateTimeKind.Utc);
        var loss = Result(3, 1, 1, 0);
        loss.KickoffUtc = new DateTime(2026, 6, 8, 12, 0, 0, DateTimeKind.Utc);

        var table = StandingsCalculator.Calculate(BuildTournament(), teams, [win, loss], groupId: 1);
        var alpha = table.Single(row => row.TeamName == "Alpha");

        Assert.Equal(["L", "W"], alpha.Form);
    }
}

public class FixtureGeneratorTests
{
    private static Tournament BuildTournament(int rounds = 1) => new()
    {
        Id = 1,
        GroupRounds = rounds,
        TeamsAdvancingPerGroup = 2,
        Format = TournamentFormat.GroupsThenKnockout
    };

    private static List<Team> BuildTeams(int count) =>
        Enumerable.Range(1, count).Select(index => new Team { Id = index, Name = $"Team {index}", GroupId = 1 }).ToList();

    [Theory]
    [InlineData(4, 6)]
    [InlineData(5, 10)]
    [InlineData(6, 15)]
    [InlineData(8, 28)]
    public void EveryTeamPlaysEveryOtherTeamOnce(int teamCount, int expectedFixtures)
    {
        var group = new TournamentGroup { Id = 1, TournamentId = 1, Name = "Group A" };
        var fixtures = FixtureGenerator.GenerateGroupFixtures(BuildTournament(), group, BuildTeams(teamCount));

        Assert.Equal(expectedFixtures, fixtures.Count);

        var pairings = fixtures
            .Select(fixture => (Low: Math.Min(fixture.HomeTeamId!.Value, fixture.AwayTeamId!.Value),
                                High: Math.Max(fixture.HomeTeamId!.Value, fixture.AwayTeamId!.Value)))
            .ToList();

        Assert.Equal(pairings.Count, pairings.Distinct().Count());
    }

    [Fact]
    public void ADoubleRoundRobinPlaysEveryPairTwice()
    {
        var group = new TournamentGroup { Id = 1, TournamentId = 1, Name = "Group A" };
        var fixtures = FixtureGenerator.GenerateGroupFixtures(BuildTournament(rounds: 2), group, BuildTeams(4));

        Assert.Equal(12, fixtures.Count);

        // Home advantage flips on the return leg, so each ordered pairing appears exactly once.
        var ordered = fixtures.Select(fixture => (fixture.HomeTeamId, fixture.AwayTeamId)).ToList();
        Assert.Equal(ordered.Count, ordered.Distinct().Count());
    }

    [Fact]
    public void BuildsABracketWithPlaceholdersThatChainBetweenRounds()
    {
        var tournament = BuildTournament();
        tournament.HasThirdPlacePlayOff = true;

        var fixtures = FixtureGenerator.GenerateKnockoutBracket(tournament, slots: 8);

        Assert.Equal(4, fixtures.Count(fixture => fixture.Stage == MatchStage.QuarterFinal));
        Assert.Equal(2, fixtures.Count(fixture => fixture.Stage == MatchStage.SemiFinal));
        Assert.Single(fixtures, fixture => fixture.Stage == MatchStage.Final);
        Assert.Single(fixtures, fixture => fixture.Stage == MatchStage.ThirdPlacePlayOff);

        var quarterFinalLabels = fixtures
            .Where(fixture => fixture.Stage == MatchStage.QuarterFinal)
            .Select(fixture => $"Winner {FixtureGenerator.TieLabel(fixture.Stage, fixture.Round)}")
            .ToList();

        var semiFinalPlaceholders = fixtures
            .Where(fixture => fixture.Stage == MatchStage.SemiFinal)
            .SelectMany(fixture => new[] { fixture.HomePlaceholder, fixture.AwayPlaceholder })
            .ToList();

        Assert.All(quarterFinalLabels, label => Assert.Contains(label, semiFinalPlaceholders));
    }

    [Theory]
    [InlineData(6, 4)]
    [InlineData(8, 8)]
    [InlineData(3, 2)]
    [InlineData(1, 0)]

public void RoundsTheBracketDownToAPowerOfTwo(int slots, int expected)
    {
        Assert.Equal(expected, FixtureGenerator.NormaliseBracketSize(slots));
    }
}

